CREATE OR REPLACE FUNCTION public.srk_admin_update_booking(
  p_booking_id uuid,
  p_status text,
  p_address text,
  p_district text,
  p_state text,
  p_pincode text
)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'pg_catalog', 'public', 'auth', 'pg_temp'
AS $function$
DECLARE
  v_booking public.service_bookings%rowtype;
BEGIN
  IF auth.uid() IS NULL OR NOT public.is_srk_admin() THEN
    RAISE EXCEPTION 'Admin permission required';
  END IF;
  IF p_booking_id IS NULL THEN
    RAISE EXCEPTION 'Booking ID required';
  END IF;

  IF p_address IS NULL OR length(pg_catalog.btrim(p_address)) = 0 OR length(p_address) > 300
     OR p_district IS NULL OR length(pg_catalog.btrim(p_district)) = 0 OR length(p_district) > 80
     OR p_state IS NULL OR length(pg_catalog.btrim(p_state)) = 0 OR length(p_state) > 80
     OR p_pincode IS NULL OR p_pincode !~ '^[0-9]{6}$' THEN
    RAISE EXCEPTION 'Valid address, district, state and six-digit PIN required';
  END IF;

  SELECT * INTO v_booking
    FROM public.service_bookings
   WHERE id = p_booking_id
   FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Booking not found';
  END IF;

  IF p_status IS NOT NULL THEN
    IF p_status NOT IN (
      'new','confirmed','assigned','inspection','awaiting_quote_approval',
      'quote_approved','quote_rejected','in_progress','completed','cancelled'
    ) THEN
      RAISE EXCEPTION 'Invalid booking status';
    END IF;
    IF v_booking.status = 'new' AND p_status NOT IN ('new','confirmed','cancelled') THEN
      RAISE EXCEPTION 'New booking can only remain new, be confirmed, or cancelled';
    ELSIF v_booking.status = 'confirmed' AND p_status NOT IN ('confirmed','cancelled') THEN
      RAISE EXCEPTION 'Confirmed booking can only remain confirmed or be cancelled';
    ELSIF v_booking.status NOT IN ('new','confirmed') AND p_status NOT IN (v_booking.status,'cancelled') THEN
      RAISE EXCEPTION 'Admin cannot skip booking workflow stages';
    END IF;
    IF p_status = 'assigned' AND v_booking.assigned_electrician_id IS NULL THEN
      RAISE EXCEPTION 'Electrician assignment required';
    END IF;
    IF p_status = 'cancelled' AND v_booking.payment_status = 'paid' THEN
      RAISE EXCEPTION 'Paid booking requires the verified refund workflow before cancellation';
    END IF;
  END IF;

  UPDATE public.service_bookings
     SET status = COALESCE(p_status, status),
         address = pg_catalog.btrim(p_address),
         district = pg_catalog.btrim(p_district),
         state = pg_catalog.btrim(p_state),
         pincode = p_pincode
   WHERE id = p_booking_id;

  RETURN pg_catalog.jsonb_build_object('success', true);
END;
$function$;

REVOKE ALL ON FUNCTION public.srk_admin_update_booking(uuid,text,text,text,text,text) FROM PUBLIC;
REVOKE ALL ON FUNCTION public.srk_admin_update_booking(uuid,text,text,text,text,text) FROM anon;
GRANT EXECUTE ON FUNCTION public.srk_admin_update_booking(uuid,text,text,text,text,text) TO authenticated;

create table if not exists public.srk_manual_payment_entries (
  id uuid primary key default gen_random_uuid(),
  booking_id uuid not null unique references public.service_bookings(id) on delete restrict,
  payment_method text not null check (payment_method in ('cash','upi','bank_transfer')),
  amount numeric(12,2) not null check (amount > 0 and amount <= 10000000),
  payment_reference text not null check (length(trim(payment_reference)) between 4 and 120),
  note text check (note is null or length(note) <= 250),
  recorded_by uuid not null references auth.users(id) on delete restrict,
  recorded_at timestamptz not null default now()
);

alter table public.srk_manual_payment_entries enable row level security;
revoke all on table public.srk_manual_payment_entries from public, anon, authenticated;

create or replace function public.srk_admin_record_manual_payment(
  p_booking_id uuid,
  p_method text,
  p_reference text,
  p_note text default null
) returns jsonb
language plpgsql
security definer
set search_path = pg_catalog, public, auth, pg_temp
as $function$
declare
  v_booking public.service_bookings%rowtype;
  v_total numeric(12,2);
  v_method text;
  v_reference text;
begin
  if auth.uid() is null or not public.is_srk_admin() then
    raise exception 'Admin access required' using errcode = '42501';
  end if;
  if p_booking_id is null then
    raise exception 'Booking ID is required';
  end if;
  v_method := lower(trim(coalesce(p_method,'')));
  if v_method not in ('cash','upi','bank_transfer') then
    raise exception 'Payment method must be cash, upi, or bank_transfer';
  end if;
  v_reference := trim(coalesce(p_reference,''));
  if length(v_reference) < 4 or length(v_reference) > 120 then
    raise exception 'A valid receipt number or payment reference is required';
  end if;
  if p_note is not null and length(p_note) > 250 then
    raise exception 'Payment note is too long';
  end if;

  select * into v_booking
  from public.service_bookings
  where id = p_booking_id
  for update;
  if not found then raise exception 'Booking not found'; end if;
  if v_booking.status <> 'completed' or v_booking.quote_status <> 'approved' then
    raise exception 'Only completed bookings with an approved quote can be marked paid';
  end if;
  if v_booking.assigned_electrician_id is null then
    raise exception 'Booking has no assigned electrician';
  end if;
  if v_booking.payment_status = 'paid' or v_booking.payment_status = 'refunded' then
    raise exception 'Booking already has a paid or refunded payment';
  end if;
  if v_booking.razorpay_order_id is not null or v_booking.razorpay_payment_id is not null then
    raise exception 'Razorpay-linked bookings must be paid only through verified Razorpay flow';
  end if;
  if exists (select 1 from public.srk_manual_payment_entries e where e.booking_id = p_booking_id) then
    raise exception 'A manual payment entry already exists for this booking';
  end if;
  if v_booking.service_charge is null or v_booking.service_charge < 0 or v_booking.materials_amount < 0 then
    raise exception 'Approved quote breakdown is invalid';
  end if;
  v_total := round(v_booking.service_charge + v_booking.materials_amount,2);
  if v_total < 1 or v_total > 10000000 or round(coalesce(v_booking.quoted_amount,-1),2) <> v_total then
    raise exception 'Approved quote total does not match the service and materials breakdown';
  end if;

  insert into public.srk_manual_payment_entries
    (booking_id,payment_method,amount,payment_reference,note,recorded_by)
  values
    (p_booking_id,v_method,v_total,v_reference,nullif(trim(coalesce(p_note,'')),''),auth.uid());

  update public.service_bookings
  set payment_method = case v_method
        when 'cash' then 'Cash'
        when 'upi' then 'UPI'
        else 'Bank Transfer'
      end,
      payment_status = 'paid',
      amount_paid = v_total,
      payment_verified_at = now()
  where id = p_booking_id;

  return jsonb_build_object(
    'success',true,
    'booking_id',p_booking_id,
    'payment_method',v_method,
    'amount',v_total,
    'reference',v_reference
  );
end;
$function$;

revoke all on function public.srk_admin_record_manual_payment(uuid,text,text,text) from public, anon;
grant execute on function public.srk_admin_record_manual_payment(uuid,text,text,text) to authenticated;

create or replace function public.srk_create_electrician_payable()
returns trigger
language plpgsql
security definer
set search_path to 'pg_catalog','public','pg_temp'
as $function$
declare
  v_service numeric(12,2);
  v_materials numeric(12,2);
  v_total numeric(12,2);
  v_rate numeric(7,2);
  v_commission numeric(12,2);
begin
  if new.payment_status = 'paid'
     and new.status = 'completed'
     and new.quote_status = 'approved'
     and new.assigned_electrician_id is not null
     and new.payment_verified_at is not null
     and (
       new.razorpay_payment_id is not null
       or exists (
         select 1 from public.srk_manual_payment_entries e
         where e.booking_id = new.id and e.amount = round(coalesce(new.amount_paid,0),2)
       )
     ) then
    v_service := round(coalesce(new.service_charge,0),2);
    v_materials := round(coalesce(new.materials_amount,0),2);
    v_total := round(v_service + v_materials,2);
    v_rate := new.commission_rate;

    if v_rate is null or v_rate < 0 or v_rate > 100 then
      raise exception 'Commission rate must be between 0 and 100; payout ledger not created';
    end if;
    if round(coalesce(new.amount_paid,0),2) <> v_total then
      raise exception 'Verified payment amount does not match approved quote total; payout ledger not created';
    end if;

    v_commission := round(v_service * v_rate / 100,2);

    insert into public.srk_electrician_payouts (
      booking_id,electrician_profile_id,razorpay_payment_id,
      gross_service_amount,materials_amount,platform_commission,
      electrician_payable,payout_status
    ) values (
      new.id,new.assigned_electrician_id,new.razorpay_payment_id,
      v_service,v_materials,v_commission,
      round(v_service + v_materials - v_commission,2),'pending'
    )
    on conflict (booking_id) do update set
      electrician_profile_id = excluded.electrician_profile_id,
      razorpay_payment_id = excluded.razorpay_payment_id,
      gross_service_amount = excluded.gross_service_amount,
      materials_amount = excluded.materials_amount,
      platform_commission = excluded.platform_commission,
      electrician_payable = excluded.electrician_payable,
      updated_at = now()
    where public.srk_electrician_payouts.payout_status = 'pending';
  elsif new.payment_status = 'refunded' then
    update public.srk_electrician_payouts
    set payout_status = 'refunded',updated_at = now()
    where booking_id = new.id and payout_status = 'pending';
  end if;
  return new;
end;
$function$;

create table if not exists public.srk_manual_refund_entries (
  id uuid primary key default gen_random_uuid(),
  booking_id uuid not null unique references public.service_bookings(id) on delete restrict,
  payment_entry_id uuid not null unique references public.srk_manual_payment_entries(id) on delete restrict,
  amount numeric(12,2) not null check (amount > 0 and amount <= 10000000),
  refund_reference text not null check (length(trim(refund_reference)) between 4 and 120),
  note text check (note is null or length(note) <= 250),
  recorded_by uuid not null references auth.users(id) on delete restrict,
  recorded_at timestamptz not null default now()
);
alter table public.srk_manual_refund_entries enable row level security;
revoke all on table public.srk_manual_refund_entries from public, anon, authenticated;

create or replace function public.srk_admin_record_manual_refund(
  p_booking_id uuid,
  p_reference text,
  p_note text default null
) returns jsonb
language plpgsql
security definer
set search_path = pg_catalog, public, auth, pg_temp
as $function$
declare
  v_booking public.service_bookings%rowtype;
  v_payment public.srk_manual_payment_entries%rowtype;
  v_reference text;
  v_paid_payout boolean;
begin
  if auth.uid() is null or not public.is_srk_admin() then
    raise exception 'Admin access required' using errcode = '42501';
  end if;
  if p_booking_id is null then raise exception 'Booking ID is required'; end if;
  v_reference := trim(coalesce(p_reference,''));
  if length(v_reference) < 4 or length(v_reference) > 120 then
    raise exception 'A valid refund UTR / provider reference is required';
  end if;
  if p_note is not null and length(p_note) > 250 then
    raise exception 'Refund note is too long';
  end if;

  select * into v_booking from public.service_bookings
  where id = p_booking_id for update;
  if not found then raise exception 'Booking not found'; end if;
  if v_booking.payment_status <> 'paid' or v_booking.payment_verified_at is null then
    raise exception 'Only verified paid bookings can be refunded';
  end if;
  if v_booking.razorpay_order_id is not null or v_booking.razorpay_payment_id is not null then
    raise exception 'Razorpay-linked refunds must be completed and reconciled through Razorpay';
  end if;
  select * into v_payment from public.srk_manual_payment_entries
  where booking_id = p_booking_id for update;
  if not found then raise exception 'Manual payment audit record not found'; end if;
  if round(coalesce(v_booking.amount_paid,0),2) <> v_payment.amount then
    raise exception 'Recorded payment amount does not match booking amount';
  end if;
  if exists (select 1 from public.srk_manual_refund_entries r where r.booking_id = p_booking_id) then
    raise exception 'A refund has already been recorded for this booking';
  end if;
  select exists(select 1 from public.srk_electrician_payouts p
                where p.booking_id = p_booking_id and p.payout_status = 'paid')
    into v_paid_payout;
  if v_paid_payout then
    raise exception 'Electrician payout is already paid; refund requires separate recovery and reconciliation';
  end if;

  insert into public.srk_manual_refund_entries
    (booking_id,payment_entry_id,amount,refund_reference,note,recorded_by)
  values
    (p_booking_id,v_payment.id,v_payment.amount,v_reference,
     nullif(trim(coalesce(p_note,'')),''),auth.uid());

  update public.service_bookings
  set payment_status = 'refunded'
  where id = p_booking_id;

  return jsonb_build_object('success',true,'booking_id',p_booking_id,
    'amount',v_payment.amount,'refund_reference',v_reference);
end;
$function$;

revoke all on function public.srk_admin_record_manual_refund(uuid,text,text) from public, anon;
grant execute on function public.srk_admin_record_manual_refund(uuid,text,text) to authenticated;

CREATE OR REPLACE FUNCTION public.srk_admin_mark_electrician_payout_paid(
  p_payout_id uuid,
  p_method text,
  p_reference text,
  p_note text DEFAULT NULL
)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'pg_catalog', 'public', 'auth', 'pg_temp'
AS $function$
DECLARE
  v_row public.srk_electrician_payouts%rowtype;
  v_booking_id uuid;
BEGIN
  IF auth.uid() IS NULL OR NOT public.is_srk_admin() THEN
    RAISE EXCEPTION 'Admin access required' USING errcode = '42501';
  END IF;
  IF p_payout_id IS NULL THEN
    RAISE EXCEPTION 'Payout ID is required';
  END IF;
  IF p_method IS NULL OR p_method NOT IN ('upi','bank') THEN
    RAISE EXCEPTION 'Payout method must be upi or bank';
  END IF;
  IF p_reference IS NULL OR pg_catalog.length(pg_catalog.btrim(p_reference)) < 4
     OR pg_catalog.length(pg_catalog.btrim(p_reference)) > 120 THEN
    RAISE EXCEPTION 'Valid UTR / UPI reference is required';
  END IF;
  IF p_note IS NOT NULL AND pg_catalog.length(p_note) > 250 THEN
    RAISE EXCEPTION 'Payout note is too long';
  END IF;

  -- Global lock order: booking first, then payout. Manual refund uses the same
  -- booking-first order, so refund and payout settlement cannot pass each other.
  SELECT booking_id INTO v_booking_id
    FROM public.srk_electrician_payouts
   WHERE id = p_payout_id;
  IF NOT FOUND OR v_booking_id IS NULL THEN
    RAISE EXCEPTION 'Payout record not found or has no booking';
  END IF;

  PERFORM 1
    FROM public.service_bookings
   WHERE id = v_booking_id
   FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Payout booking not found';
  END IF;

  SELECT * INTO v_row
    FROM public.srk_electrician_payouts
   WHERE id = p_payout_id
   FOR UPDATE;
  IF NOT FOUND OR v_row.booking_id IS DISTINCT FROM v_booking_id THEN
    RAISE EXCEPTION 'Payout record changed; retry the operation';
  END IF;
  IF v_row.payout_status <> 'pending' THEN
    RAISE EXCEPTION 'Only pending payouts can be marked paid';
  END IF;

  IF NOT EXISTS (
    SELECT 1
      FROM public.service_bookings b
     WHERE b.id = v_row.booking_id
       AND b.status = 'completed'
       AND b.quote_status = 'approved'
       AND b.payment_status = 'paid'
       AND b.payment_verified_at IS NOT NULL
       AND (
         (
           v_row.razorpay_payment_id IS NOT NULL
           AND b.razorpay_payment_id = v_row.razorpay_payment_id
         )
         OR
         (
           v_row.razorpay_payment_id IS NULL
           AND b.razorpay_payment_id IS NULL
           AND EXISTS (
             SELECT 1
               FROM public.srk_manual_payment_entries e
              WHERE e.booking_id = b.id
                AND pg_catalog.round(pg_catalog.coalesce(e.amount,0),2) =
                    pg_catalog.round(pg_catalog.coalesce(b.amount_paid,0),2)
           )
         )
       )
       AND b.assigned_electrician_id = v_row.electrician_profile_id
       AND pg_catalog.round(pg_catalog.coalesce(b.amount_paid,0),2) =
           pg_catalog.round(pg_catalog.coalesce(b.service_charge,0) + pg_catalog.coalesce(b.materials_amount,0),2)
       AND pg_catalog.round(pg_catalog.coalesce(v_row.gross_service_amount,0),2) =
           pg_catalog.round(pg_catalog.coalesce(b.service_charge,0),2)
       AND pg_catalog.round(pg_catalog.coalesce(v_row.materials_amount,0),2) =
           pg_catalog.round(pg_catalog.coalesce(b.materials_amount,0),2)
       AND pg_catalog.round(pg_catalog.coalesce(v_row.platform_commission,0),2) =
           pg_catalog.round(pg_catalog.coalesce(b.service_charge,0) * b.commission_rate / 100,2)
       AND pg_catalog.round(pg_catalog.coalesce(v_row.electrician_payable,0),2) =
           pg_catalog.round(pg_catalog.coalesce(b.service_charge,0) + pg_catalog.coalesce(b.materials_amount,0)
             - pg_catalog.round(pg_catalog.coalesce(b.service_charge,0) * b.commission_rate / 100,2),2)
  ) THEN
    RAISE EXCEPTION 'Booking payment or payout ledger does not match verified booking; payout blocked';
  END IF;

  UPDATE public.srk_electrician_payouts
     SET payout_status = 'paid',
         payout_method = p_method,
         payout_reference = pg_catalog.btrim(p_reference),
         payout_note = pg_catalog.nullif(pg_catalog.btrim(p_note),''),
         paid_by = auth.uid(),
         paid_at = pg_catalog.now(),
         updated_at = pg_catalog.now()
   WHERE id = p_payout_id;
  RETURN pg_catalog.jsonb_build_object('success', true, 'payout_id', p_payout_id, 'status', 'paid');
END;
$function$;

