-- Push subscriptions are private to the authenticated electrician account.
create table if not exists public.srk_push_subscriptions (
  id uuid primary key default gen_random_uuid(),
  user_id uuid not null references auth.users(id) on delete cascade,
  endpoint text not null unique,
  p256dh text not null,
  auth text not null,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  constraint srk_push_endpoint_length check (length(endpoint) between 1 and 2048),
  constraint srk_push_p256dh_length check (length(p256dh) between 1 and 256),
  constraint srk_push_auth_length check (length(auth) between 1 and 256)
);

create index if not exists srk_push_subscriptions_user_id_idx
  on public.srk_push_subscriptions(user_id);

alter table public.srk_push_subscriptions enable row level security;

drop policy if exists srk_push_subscriptions_select_own on public.srk_push_subscriptions;
create policy srk_push_subscriptions_select_own
  on public.srk_push_subscriptions for select to authenticated
  using (user_id = (select auth.uid()));

drop policy if exists srk_push_subscriptions_insert_own on public.srk_push_subscriptions;
create policy srk_push_subscriptions_insert_own
  on public.srk_push_subscriptions for insert to authenticated
  with check (user_id = (select auth.uid()));

drop policy if exists srk_push_subscriptions_update_own on public.srk_push_subscriptions;
create policy srk_push_subscriptions_update_own
  on public.srk_push_subscriptions for update to authenticated
  using (user_id = (select auth.uid()))
  with check (user_id = (select auth.uid()));

drop policy if exists srk_push_subscriptions_delete_own on public.srk_push_subscriptions;
create policy srk_push_subscriptions_delete_own
  on public.srk_push_subscriptions for delete to authenticated
  using (user_id = (select auth.uid()));

revoke all on public.srk_push_subscriptions from anon, public;
grant select, insert, update, delete on public.srk_push_subscriptions to authenticated;

-- Keep the privileged ownership-transfer implementation outside exposed API schemas.
create schema if not exists private;
revoke all on schema private from public, anon;
grant usage on schema private to authenticated;

create or replace function private.srk_save_push_subscription(
  p_endpoint text,
  p_p256dh text,
  p_auth text
)
returns void
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_user_id uuid := auth.uid();
begin
  if v_user_id is null then
    raise exception 'Authentication required' using errcode = '42501';
  end if;

  if p_endpoint is null or length(p_endpoint) < 1 or length(p_endpoint) > 2048
     or left(p_endpoint, 8) <> 'https://'
     or p_p256dh is null or length(p_p256dh) < 1 or length(p_p256dh) > 256
     or p_auth is null or length(p_auth) < 1 or length(p_auth) > 256 then
    raise exception 'Invalid push subscription';
  end if;

  insert into public.srk_push_subscriptions(user_id, endpoint, p256dh, auth, updated_at)
  values (v_user_id, p_endpoint, p_p256dh, p_auth, now())
  on conflict (endpoint) do update
    set user_id = excluded.user_id,
        p256dh = excluded.p256dh,
        auth = excluded.auth,
        updated_at = now();
end;
$$;

revoke all on function private.srk_save_push_subscription(text, text, text) from public, anon;
grant execute on function private.srk_save_push_subscription(text, text, text) to authenticated;

-- Exposed RPC wrapper runs as the caller; privileged work remains in private schema.
create or replace function public.srk_save_push_subscription(
  p_endpoint text,
  p_p256dh text,
  p_auth text
)
returns void
language plpgsql
security invoker
set search_path = ''
as $$
begin
  perform private.srk_save_push_subscription(p_endpoint, p_p256dh, p_auth);
end;
$$;

revoke all on function public.srk_save_push_subscription(text, text, text) from public, anon;
grant execute on function public.srk_save_push_subscription(text, text, text) to authenticated;

create or replace function private.srk_notify_job_offer_push()
returns trigger
language plpgsql
security definer
set search_path = pg_catalog
as $function$
declare
  v_secret text;
  v_payload jsonb;
begin
  select decrypted_secret into v_secret
  from vault.decrypted_secrets
  where name = 'PUSH_WEBHOOK_SECRET'
  limit 1;

  if v_secret is null or length(v_secret) < 24 then
    raise warning 'SRK push webhook secret is missing or too short; notification request was not queued';
    return coalesce(new, old);
  end if;

  v_payload := jsonb_build_object(
    'type', tg_op,
    'table', tg_table_name,
    'schema', tg_table_schema,
    'record', case when tg_op = 'DELETE' then to_jsonb(old) else to_jsonb(new) end,
    'old_record', case when tg_op = 'UPDATE' or tg_op = 'DELETE' then to_jsonb(old) else null end
  );

  perform net.http_post(
    url := 'https://gnqhoaqatmoiwwhgzkgm.supabase.co/functions/v1/push-job-offer',
    headers := jsonb_build_object(
      'Content-Type', 'application/json',
      'x-srk-push-secret', v_secret
    ),
    body := v_payload,
    timeout_milliseconds := 5000
  );

  return coalesce(new, old);
end;
$function$;

revoke all on function private.srk_notify_job_offer_push() from public, anon, authenticated;

drop trigger if exists trg_srk_push_job_offer on public.job_offers;
create trigger trg_srk_push_job_offer
after insert or update on public.job_offers
for each row execute function private.srk_notify_job_offer_push();

create or replace function public.srk_get_my_assigned_cash_payment(p_booking_id uuid)
returns jsonb
language plpgsql
stable
security definer
set search_path = pg_catalog, public, auth, pg_temp
as $function$
declare
  v_uid uuid := auth.uid();
  v_profile_id uuid;
  v_booking public.service_bookings%rowtype;
begin
  if v_uid is null then
    raise exception 'Authentication required' using errcode = '42501';
  end if;

  select p.id into v_profile_id
  from public.electrician_profiles p
  where (p.user_id = v_uid or p.auth_user_id = v_uid)
    and p.verification_status = 'approved'
    and p.active = true
  limit 1;

  if v_profile_id is null then
    raise exception 'Approved active electrician required' using errcode = '42501';
  end if;

  select b.* into v_booking
  from public.service_bookings b
  where b.id = p_booking_id
    and b.assigned_electrician_id = v_profile_id
  limit 1;

  if not found then
    raise exception 'Assigned booking not found' using errcode = '42501';
  end if;

  return jsonb_build_object(
    'booking_id', v_booking.id,
    'status', v_booking.status,
    'payment_method', v_booking.payment_method,
    'payment_status', v_booking.payment_status,
    'quote_status', v_booking.quote_status,
    'quoted_amount', v_booking.quoted_amount,
    'can_confirm_cash',
      v_booking.status = 'completed'
      and v_booking.quote_status = 'approved'
      and lower(coalesce(v_booking.payment_method, '')) in ('cash', 'नकद (cash)', 'नकद')
      and coalesce(v_booking.payment_status, 'unpaid') in ('unpaid', 'pending')
      and coalesce(v_booking.quoted_amount, 0) > 0
  );
end;
$function$;

revoke all on function public.srk_get_my_assigned_cash_payment(uuid) from public, anon;
grant execute on function public.srk_get_my_assigned_cash_payment(uuid) to authenticated;
